Translate("esMX", "grull-hawkwind", {
	title = "Grull Hawkwind",
	subtitle = "Cazador de la Mesa de la Nube Roja",
	found = "Campamento Narache, en la Mesa de la Nube Roja",
	hint = [=[Encuentre al hijo del jefe, que pone a prueba a los jóvenes cazadores de Narache.]=],
	allegiance = "Tauren · Campamento Narache",
	aliases = { "Grull" },
	sections = {
		{
			title = "Resumen",
			text = [=[Grull Hawkwind es hijo del jefe {link:chief-hawkwind}Hawkwind{/link} y cazador de la {link:red-cloud-mesa}Mesa de la Nube Roja{/link}. Pone a prueba a los jóvenes que llegan al {link:camp-narache}Campamento Narache{/link} antes de que se presenten ante su padre. Enseña que los {link:tauren}tauren{/link} cazan por necesidad además de por deporte, y que una bestia se caza para alimentar y vestir a la tribu, nunca como un simple trofeo.]=],
		},
		{
			title = "Importancia",
			text = [=[Grull da a los jóvenes su primera cacería, y con ella la primera lección de la vida {link:tauren}tauren{/link}: tomar de la tierra solo lo que la tribu necesita.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envía a los jóvenes a cazar zancudos de llanura para obtener carne y plumas.
• Pide pieles de puma de montaña para vestir a los niños y remendar las tiendas.
• Envía cazadores contra los jabalíes de batalla del {link:brambleblade-ravine}Barranco Cortazarza{/link}.]=],
		},
	},
	mentions = {
		{ text = "Empieza la caza" },
		{ text = "Continúa la caza" },
		{ text = "Los jabalíes de batalla" },
