Translate("esMX", "baine-bloodhoof", {
	title = "Baine Bloodhoof",
	subtitle = "Jefe del Poblado Pezuña de Sangre",
	found = "El centro del Poblado Pezuña de Sangre",
	hint = [=[Busque al hijo del Gran Jefe, que dirige el Poblado Pezuña de Sangre.]=],
	allegiance = "Tauren · tribu Pezuña de Sangre · Horda",
	aliases = { "Baine" },
	sections = {
		{
			title = "Resumen",
			text = [=[Baine Bloodhoof es hijo de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} y jefe del {link:bloodhoof-village}Poblado Pezuña de Sangre{/link}. Gobierna el corazón de {link:mulgore}Mulgore{/link} mientras su padre gobierna desde {link:thunder-bluff}Cima del Trueno{/link}. Es paciente con quienes quieren compartir la tierra, y severo con quienes no. Ha visto muchos de los conflictos que hieren el mundo, y espera que los jóvenes de su tribu vean menos.]=],
		},
		{
			title = "Importancia",
			text = [=[Baine es la nueva generación de los Pezuña de Sangre. Los jóvenes que pasan por su poblado aprenden de él lo que significa defender la patria {link:tauren}tauren{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Continúa los {link:rites-of-the-earthmother}Ritos de la Madre Tierra{/link}, y envía a los jóvenes al líder espiritual {link:zarlman-two-moons}Zarlman Two-Moons{/link} para el Rito de Visión.
• Ordenó hacer retroceder a los {link:palemane-gnolls}gnolls Crines Pálidas{/link} cuando rechazaron todo intento de paz.
• Ordenó destruir las herramientas de los excavadores enanos.
• A veces pide ayuda a los {link:longwalkers}Longwalkers{/link}, los exploradores de su padre.
• En estos días dirigió la defensa contra una partida de asalto Galak.]=],
		},
	},
	chapters = {
		{
			title = "Compartir la tierra",
			hint = "Conozca el juicio del jefe sobre los gnolls de Mulgore.",
			text = [=[Los {link:palemane-gnolls}gnolls Crines Pálidas{/link} llegaron a {link:mulgore}Mulgore{/link} y mataron su fauna sin freno. Los {link:tauren}tauren{/link} intentaron una y otra vez llegar a ellos con palabras. Baine concluyó al fin que las palabras ya no eran la respuesta. Quería mostrar a los jóvenes lo terrible que puede llegar a ser incluso una pequeña amenaza si no se la frena.]=],
		},
		{
			title = "Nuestro antiguo enemigo",
			hint = "Ocúpese de los centauros que han entrado en Mulgore.",
			text = [=[Cuando le llegó el informe de la {link:longwalkers}Longwalker{/link} Malah, caída, Baine lo leyó en silencio. Luego declaró que los {link:tauren}tauren{/link} no cederían ni una brizna de hierba a los centauros. Envió guerreros a golpear el campamento Galak antes de que sus jinetes pudieran alcanzar su poblado, y pidió que le trajeran la cabeza de su líder como advertencia para otros.]=],
		},
		{
			title = "El hijo cautivo",
			hint = "Conozca los días en que los centauros se llevaron a Baine.",
			text = [=[En los meses posteriores al asentamiento de los {link:tauren}tauren{/link} en {link:mulgore}Mulgore{/link}, los centauros capturaron a Baine. Su padre cayó en una desesperación tan honda que no quería gobernar. Fueron el {link:orcs}orco{/link} {link:rexxar}Rexxar{/link} y el tauren Bovan Windtotem quienes encontraron a Baine y lo trajeron a casa. Cuando Baine envía hoy a los jóvenes ante su padre, habla con orgullo del día en que {link:cairne-bloodhoof}Cairne{/link} cabalgó con {link:thrall}Thrall{/link} para reconquistar estas llanuras.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rites-of-the-earthmother}Ritos de la Madre Tierra{/link}, traídos del jefe {link:chief-hawkwind}Hawkwind{/link}]=],
		},
		{ text = "Rito de Visión" },
		{ text = "Excavaciones enanas" },
		{ text = "Nuestro antiguo enemigo, el informe que recibió" },
		{ text = "El Gran Jefe" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "su padre" },
		{ id = "chief-hawkwind", name = "Jefe Hawkwind", note = "le envía a los jóvenes" },
		{ id = "zarlman-two-moons", name = "Zarlman Two-Moons", note = "líder espiritual de su poblado" },
		{ id = "brave-wildrunner", name = "Valiente Wildrunner", note = "un valiente de su poblado" },
		{ id = "herak-the-pillager", name = "Herak el Saqueador", note = "enemigo" },
	},
})

