Translate("esMX", "muln-earthfury", {
	title = "Muln Earthfury",
	subtitle = "Anciano del Anillo de la Tierra",
	found = "Camp Gev'rek, en la Skywatcher Plateau",
	hint = [=[Busque al anciano chamán que da la bienvenida a los Skyborne en Mulgore.]=],
	allegiance = "Anillo de la Tierra · Tauren",
	aliases = { "Muln" },
	sections = {
		{
			title = "Resumen",
			text = [=[Muln Earthfury es un chamán {link:tauren}tauren{/link} y uno de los líderes del {link:earthen-ring}Anillo de la Tierra{/link}, el consejo que guarda el equilibrio de los {link:elements}elementos{/link}. En estos días, su deber hacia los espíritus lo llevó más allá del propio mundo, a {link:skywall}Skywall{/link}, el reino del aire. Allí respondió a la llamada de los {link:windshapers}Windshapers{/link}, y cuando volvió los trajo consigo.]=],
		},
		{
			title = "Importancia",
			text = [=[Muln es el puente entre los {link:skyborne}Skyborne{/link} y {link:azeroth}Azeroth{/link}. A través de él, los {link:windshapers}Windshapers{/link} encontraron el {link:earthen-ring}Anillo de la Tierra{/link}, y a través del Anillo encontraron a la {link:horde}Horda{/link}. Los elfos que bajan a {link:mulgore}Mulgore{/link} son sus huéspedes, y conocen el mundo al principio a través de su campamento y sus consejos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Respondió a la súplica de la líder de los {link:windshapers}Windshapers{/link}, {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, cuyo hogar se desmoronaba.
• Fue con chamanes del {link:earthen-ring}Anillo de la Tierra{/link} a {link:zephras-isle}Zephras Isle{/link} para ayudar a los {link:skyborne}Skyborne{/link}.
• Se enfrentó a uno de los grandes señores del viento y le dijo que el Anillo no tenía disputa alguna con él.
• Advirtió a los Windshapers de los señores elementales, y de que había buenas razones para temer a {link:al-akir}Al'Akir{/link}.
• Abrió una ruta de navíos skycutter entre Zephras Isle y {link:mulgore}Mulgore{/link}.
• Mantiene el campamento de la {link:camp-gev-rek}Skywatcher Plateau{/link} adonde llegan los recién llegados.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Muln antes de estos días. Las crónicas de esta era no registran cuándo llegó a dirigir el Anillo, ni cómo lo alcanzó {link:ayessa-dawnsinger}Ayessa{/link} por primera vez a través de los planos.]=],
		},
	},
	chapters = {
		{
			title = "Ayuda desde abajo",
			hint = [=[Permanezca junto a los Windshapers en su hora más oscura en Zephras Isle.]=],
			text = [=[Los {link:windshapers}Windshapers{/link} habían pedido ayuda, y la ayuda tardaba en llegar. Cuando Muln y los chamanes del {link:earthen-ring}Anillo de la Tierra{/link} llegaron por fin, la batalla contra el culto de la suma sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link} ya estaba en su apogeo. Pidió perdón a {link:ayessa-dawnsinger}Ayessa{/link} por llegar tarde. Cuando el {link:al-akir}Señor del Viento{/link} del Este cayó sobre ellos, Muln habló por el Anillo: no tenían disputa alguna con él, y solo pedían que los dejara en paz. Cuando terminó la batalla, volvió de inmediato a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "La advertencia",
			hint = [=[Averigüe qué dijo el Anillo de la Tierra a los Windshapers sobre el Señor del Viento.]=],
			text = [=[Muln le contó a {link:ayessa-dawnsinger}Ayessa{/link} muchas cosas de los señores elementales. Lo que le contó la dejó asustada. Las salvaguardas que habían ocultado {link:zephras-isle}Zephras Isle{/link} habían desaparecido, y nada se interponía entre la isla y {link:al-akir}Al'Akir{/link} en su propio dominio. La Suma Anciana de los {link:skyborne}Skyborne{/link} miraba más lejos: para un señor elemental, podían pasar años o incluso décadas antes de que volviera los ojos hacia ellos.]=],
		},
		{
			title = "La ruta de los skycutter",
			hint = [=[Embarque desde Zephras Isle hacia la tierra del Anillo de la Tierra.]=],
			text = [=[Muln trabajó duro para que la travesía fuera segura. Viajes de prueba navegaron entre la isla y {link:mulgore}Mulgore{/link}, donde el {link:earthen-ring}Anillo de la Tierra{/link} tiene su hogar, hasta que los skycutter hicieron la ruta con regularidad y los primeros {link:skyborne}Skyborne{/link} ya esperaban al otro lado.]=],
		},
	},
	mentions = {
		{
			text = [=[El {link:earthen-ring}Anillo de la Tierra{/link}, su campamento en {link:mulgore}Mulgore{/link}]=],
		},
		{ text = "Hijo de la naturaleza" },
		{ text = "Explorar la {link:horde}Horda{/link}" },
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "recibe a los Windshapers en su campamento" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "Gran Jefe de su pueblo" },
		{ id = "thrall", name = "Thrall", note = "jefe de guerra de la Horda y chamán" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "del Círculo Cenarion, que acoge a sus huéspedes" },
	},
})

