		{
			title = "Resumen",
			text = [=[Herak el Saqueador dirige una pequeña partida de asalto de {link:centaurs}centauros{/link} Galak que se ha colado en {link:mulgore}Mulgore{/link} desde el este. Sus jinetes mataron a la {link:longwalkers}Longwalker{/link} Malah Longwind con flechas por la espalda y levantaron un campamento dentro de las fronteras {link:tauren}tauren{/link}. Herak reclama las llanuras para los Galak y jura venganza contra los tauren. Sus jinetes pensaban descansar antes de atacar el {link:bloodhoof-village}Poblado Pezuña de Sangre{/link}, y mandar a buscar más a {link:the-barrens}Los Baldíos{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Herak es una señal de que los centauros no han olvidado {link:mulgore}Mulgore{/link}, y de que la victoria de {link:cairne-bloodhoof}Cairne{/link} todavía debe defenderse.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sus jinetes mataron a la {link:longwalkers}Longwalker{/link} Malah.
• Llevó una partida de asalto a {link:mulgore}Mulgore{/link}.]=],
		},
	},
	mentions = {
		{ text = "Expulsarlos" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "quiere su cabeza" },
	},
})

Translate("esMX", "bristleback-quilboar", {
	title = "Jabaespines Erizapúas",
	aliases = { "jabaespines Erizapúas", "Erizapúas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Erizapúas son la tribu de {link:quilboar}jabaespines{/link} que vive en {link:mulgore}Mulgore{/link}. Estaban allí antes de que los {link:tauren}tauren{/link} se asentaran en las llanuras, y están en guerra con ellos desde entonces. Desde su poblado espinoso del {link:brambleblade-ravine}Barranco Cortazarza{/link} atacan la {link:red-cloud-mesa}Mesa de la Nube Roja{/link}, y sus asaltantes llegan tan al norte como el cementerio de {link:red-rocks}Roca Roja{/link}.]=],
		},
		{
			title = "Formas de guerra",
			text = [=[Los Erizapúas luchan desde la emboscada. Sus guerreros acechan a las partidas de caza {link:tauren}tauren{/link} y se cuelan de noche en el {link:camp-narache}Campamento Narache{/link}. Sus chamanes luchan junto a ellos. Adiestran jabalíes de batalla, los grandes jabalíes del barranco, para que sean malvados, y los sueltan en los cazaderos tauren. Su jefe de guerra trazó planes para un largo asedio del Campamento Narache.]=],
		},
		{
			title = "En estos días",
			text = [=[Los jóvenes {link:tauren}tauren{/link} de {link:camp-narache}Narache{/link} prueban su fuerza contra los Erizapúas, y los cinturones de los asaltantes caídos son los primeros trofeos del Rito de Fuerza. Últimamente, intrusos Erizapúas han estado devastando las tumbas de {link:red-rocks}Roca Roja{/link}. Su jefe, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, gobierna el barranco.]=],
		},
	},
})

Translate("esMX", "palemane-gnolls", {
	title = "Gnolls Crines Pálidas",
	aliases = { "gnolls Crines Pálidas", "Crines Pálidas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Crines Pálidas son una tribu de {link:gnolls}gnolls{/link} que se ha asentado en {link:mulgore}Mulgore{/link}. Tienen su guarida en la cueva de la {link:palemane-rock}Roca Crines Pálidas{/link}, en las colinas del oeste, y mantienen campamentos al sur del {link:bloodhoof-village}Poblado Pezuña de Sangre{/link}. Son cazadores furtivos, desolladores y curtidores, y matan la fauna de las llanuras sin freno.]=],
		},
		{
			title = "Los tauren y los Crines Pálidas",
			text = [=[Los {link:tauren}tauren{/link} intentaron compartir la tierra con ellos. Una y otra vez procuraron hablar con los gnolls, y cada vez recibieron falta de respeto. El jefe {link:baine-bloodhoof}Baine Bloodhoof{/link} juzgó al fin que las palabras ya no eran la respuesta. Aun así, el Gran Jefe hizo un intento más en estos días, y envió a su {link:longwalkers}Longwalker{/link} {link:perith-stormhoof}Perith Stormhoof{/link} ante ellos. Los gnolls lo apresaron y lo retuvieron en su cueva.]=],
		},
		{
			title = "Sus guaridas",
			text = [=[Los curtidores y desolladores de la tribu trabajan las pieles de sus presas en torno a la {link:palemane-rock}Roca Crines Pálidas{/link}, mientras los cazadores furtivos recorren las colinas del oeste. Entre los campamentos al sur de Pezuña de Sangre merodea un {link:gnolls}gnoll{/link} llamado Snagglespear.]=],
		},
	},
})

Translate("esMX", "windfury-harpies", {
	title = "Arpías Viento Furioso",
	aliases = { "arpías Viento Furioso", "Viento Furioso" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Viento Furioso son las {link:harpies}arpías{/link} de {link:mulgore}Mulgore{/link}. Sus bandadas anidan en los bordes montañosos del sureste, lejos de los caminos, y sobre todo en la {link:windfury-ridge}Cresta Viento Furioso{/link}, en el extremo norte. Los {link:tauren}tauren{/link} las cuentan entre los enemigos naturales de su tierra.]=],
		},
		{
			title = "Naturaleza",
			text = [=[Las bandadas Viento Furioso están gobernadas por matriarcas, y sus brujas y hechiceras dominan el viento. Hacen presa de todo lo que camina bajo sus nidos. Su plumaje es apreciado por los {link:tauren}tauren{/link}: las plumas azules y broncíneas de las bandadas del norte se usan para los tocados que llevan los jóvenes tauren cuando se presentan ante el Gran Jefe.]=],
		},
		{
			title = "En estos días",
			text = [=[{link:ruul-eagletalon}Ruul Eagletalon{/link}, de Pezuña de Sangre, envía a jóvenes guerreros contra las bandadas del sureste como prueba de fuerza. Las bandadas del norte son más fuertes, y sus hechiceras y matriarcas dominan las alturas de la {link:windfury-ridge}Cresta Viento Furioso{/link}. Se ha visto a una {link:harpies}arpía{/link} llamada Hermana Hatelash entre los riscos del noroeste, no lejos de la meseta donde el {link:earthen-ring}Anillo de la Tierra{/link} ha instalado su campamento.]=],
		},
	},
})

Translate("esMX", "longwalkers", {
	title = "Longwalkers",
	aliases = { "Longwalker" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Longwalkers son los exploradores de más confianza de los {link:tauren}tauren{/link}. Solo responden ante el Gran Jefe {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, y llevan a cabo sus encargos más secretos. A un Longwalker se le reconoce por una cinta en la frente y un bastón emplumado. Incluso el jefe del {link:bloodhoof-village}Poblado Pezuña de Sangre{/link}, el propio hijo de Cairne, solo puede pedirles ayuda.]=],
		},
		{
			title = "Sus costumbres",
			text = [=[El secreto es la primera ley de los Longwalkers. Viajan solos, no hablan de sus misiones, y cuando a uno lo salvan de un peligro sigue solo antes que decir a nadie adónde va. Cuando un Longwalker no vuelve de una guardia, los valientes del poblado más cercano deben ir a averiguar por qué.]=],
		},
		{
			title = "En estos días",
			text = [=[Dos Longwalkers han estado en peligro en {link:mulgore}Mulgore{/link}. {link:perith-stormhoof}Perith Stormhoof{/link}, a quien {link:cairne-bloodhoof}Cairne{/link} llama su explorador de más confianza, fue enviado a tratar con los {link:palemane-gnolls}gnolls Crines Pálidas{/link} y cayó prisionero. Malah Longwind fue enviada a vigilar la frontera oriental y murió a manos de centauros Galak, con su informe todavía en la mano.]=],
		},
	},
})

Translate("esMX", "rites-of-the-earthmother", {
	title = "Ritos de la Madre Tierra",
	aliases = { "Ritos de la Madre Tierra" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Ritos de la Madre Tierra son las pruebas con las que un joven {link:tauren}tauren{/link} se gana el respeto de los ancianos de {link:thunder-bluff}Cima del Trueno{/link}. Son tres: el Rito de Fuerza, el Rito de Visión y el Rito de Sabiduría. Juntos llevan desde el primer campamento de la {link:red-cloud-mesa}Mesa de la Nube Roja{/link} hasta la morada del Gran Jefe.]=],
		},
		{
			title = "Los tres ritos",
			text = [=[• {b}El Rito de Fuerza.{/b} El jefe {link:chief-hawkwind}Hawkwind{/link} y el vidente {link:seer-graytongue}Graytongue{/link} envían a los jóvenes contra los asaltantes {link:bristleback-quilboar}Erizapúas{/link} del {link:brambleblade-ravine}Barranco Cortazarza{/link}, para que traigan sus cinturones como prueba de valor.
• {b}El Rito de Visión.{/b} En el {link:bloodhoof-village}Poblado Pezuña de Sangre{/link}, {link:zarlman-two-moons}Zarlman Two-Moons{/link} prepara el Agua de los Videntes con piedras de pozo y ambermaíz. Bebida ante la hoguera de la tribu, invoca una visión de las llanuras que lleva a quien la bebe hasta el vidente {link:seer-wiserunner}Wiserunner{/link}.
• {b}El Rito de Sabiduría.{/b} En {link:red-rocks}Roca Roja{/link}, los espíritus ancestrales dan su bendición a quienes han bebido el Agua de los Videntes.]=],
		},
		{
			title = "El final del viaje",
			text = [=[Quienes superan los ritos son honrados en {link:thunder-bluff}Cima del Trueno{/link}. Su último paso es subir a la meseta más alta y presentarse ante {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Ni siquiera entonces termina la prueba. Para conservar el lugar que han ganado, el Gran Jefe los envía a rastrear y matar a Arra'chea, un poderoso kodo de las llanuras.]=],
		},
	},
})
